import{_ as a,o as i,c as t,a2 as o}from"./chunks/framework.LJP3gfxI.js";const h=JSON.parse('{"title":"Beta and provider release policy","description":"","frontmatter":{},"headers":[],"relativePath":"spec/publication-freeze.md","filePath":"spec/publication-freeze.md"}'),r={name:"spec/publication-freeze.md"};function n(s,e,d,l,c,p){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="beta-and-provider-release-policy" tabindex="-1">Beta and provider release policy <a class="header-anchor" href="#beta-and-provider-release-policy" aria-label="Permalink to &quot;Beta and provider release policy&quot;">​</a></h1><p>The current portable contracts are the Host API <code>forms.takoform.com/v1beta1</code> and the Edge Platform Family <code>edge.forms.takoform.com/v1beta1</code>. The API and family are public <strong>Beta</strong> channels. The 15 Form Definitions remain <strong>Experimental</strong>, each at <code>definitionVersion: 0.1.0</code>; Beta does not make a Form Stable.</p><p>Provider versioning is independent. Provider <code>v2.1.1</code> is a stable SemVer release candidate targeting the Beta Host API. Its descriptor remains <code>candidate-only</code> until the owning deploy actually publishes it. This is not a provider prerelease and it is not a claim that any hosted service, Takosumi Cloud, or Form Package is GA.</p><h2 id="provider-first-release-is-allowed" tabindex="-1">Provider-first release is allowed <a class="header-anchor" href="#provider-first-release-is-allowed" aria-label="Permalink to &quot;Provider-first release is allowed&quot;">​</a></h2><p>Open records in <a href="publication-blockers.json"><code>publication-blockers.json</code></a> do <strong>not</strong> block the provider v2.1 release. The provider release gate instead locks all of these facts:</p><ul><li>exactly 15 Terraform resource schemas and resource type names;</li><li>exactly 15 <code>edge.forms.takoform.com/v1beta1</code> FormRefs, Definition digests, and package digests in <a href="../release/provider-form-identities.json"><code>release/provider-form-identities.json</code></a>;</li><li>fake-host and reference-host conformance against <code>forms.takoform.com/v1beta1</code>;</li><li>exact state compatibility: read, update, import, and delete dispatch on the FormRef recorded in state;</li><li>Beta state remains readable after a future <code>edge.forms.takoform.com/v1</code> create default is added; refresh never upgrades it implicitly;</li><li>append-only public schema identities and no overwrite of retained <code>v1alpha3</code> bytes.</li></ul><p>The provider identity ledger is independent of package artifact publication. Once provider v2.1 embeds a Beta FormRef, Definition digest, and package digest, that tuple is immutable even while the corresponding Form Package remains unpublished. A correction that breaks any Beta contract mints a new <code>v1beta2</code> Host/family identity and new FormRef; it never edits the Beta 1 bytes.</p><h2 id="what-remains-blocked" tabindex="-1">What remains blocked <a class="header-anchor" href="#what-remains-blocked" aria-label="Permalink to &quot;What remains blocked&quot;">​</a></h2><p>While any obligation in <code>publication-blockers.json</code> is open, this repository must not:</p><ul><li>publish the Beta Form Packages;</li><li>independently publish the Interface or Binding Definitions;</li><li>claim a production public Host API service is ready;</li><li>call the family Forms Stable or claim Takosumi/Takosumi Cloud GA;</li><li>claim independent-host, real-backend, or third-party ecosystem interoperability without the evidence the obligation names.</li></ul><p><code>bun run assert:publishable</code> is intentionally this stricter Form Package/public-service assertion. It is not part of the provider-first release path. Closing an obligation still requires real evidence; a passing local gate, an empty evidence array, or an invented path cannot close one.</p><p>Independent host implementations, real backend behavior, hosted operations, and third-party ecosystem use are later Stable/GA qualification obligations owned by Takoform&#39;s lifecycle authority. They remain open until measured. A Takosumi deployment may be one independent adopter, but it is not a maturity or publication authority. The local reference host proves contract coherence only.</p><h2 id="existing-immutable-history" tabindex="-1">Existing immutable history <a class="header-anchor" href="#existing-immutable-history" aria-label="Permalink to &quot;Existing immutable history&quot;">​</a></h2><p>Publication is per identity, not per product lane.</p><ul><li>Every schema identity in <a href="../release/public-schema-identities.json"><code>release/public-schema-identities.json</code></a> is append-only. Published <code>v1alpha3</code> schema bytes stay served unchanged; Beta schemas use new <code>v1beta1</code> URLs.</li><li>Provider <code>v1.0.3</code> and <code>v2.0.0</code>, their tags, and their persisted state contracts remain immutable.</li><li>The 34 Legacy Form Packages and retained admission evidence remain byte-for-byte history.</li><li>The old <code>edge.forms.takoform.com/v1alpha1</code> candidate tree is retained as source history. The Beta family was minted in a new directory and identity.</li></ul><p>Only contracts that have satisfied the recorded qualification obligations may be promoted to stable <code>v1</code>/<code>1.0.0</code> identities by a Takoform lifecycle decision. Promotion adds identities and create defaults; it does not rewrite or auto-migrate Beta state.</p>',16)])])}const u=a(r,[["render",n]]);export{h as __pageData,u as default};
